import * as THREE from 'three';
import { KITS } from '../core/config.js';
import { limbGeometry, jointGeometry, PROFILES, skinMaterial, fabricMaterial, shirtTexture, buildHead, buildHand, buildBoot } from './HumanBuilder.js';

// Procedural footballer with a joint hierarchy, so it can be animated in code
// (run, strafe, wind-up, tackle, flinch, fall, dive, throw). The body is
// generated by HumanBuilder: muscle-shaped limbs, a sculpted face, hair,
// hands with fingers, studded boots and a fabric kit with printed name/number.

function mesh(geo, mat, parent, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(geo, mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  parent.add(m);
  return m;
}

export class OpponentModel {
  constructor(def) {
    const kit = def.kit || (def.isKeeper ? KITS.keeper : KITS.opponent);
    const look = def.look;
    this.def = def;
    this.root = new THREE.Group();
    this.body = new THREE.Group(); // pivot at the feet for falls / dives
    this.root.add(this.body);
    this.hitMeshes = [];
    this.materials = [];

    const H = look.height;
    const B = look.build;
    this.scaleH = H;
    const keeper = !!def.isKeeper;
    const reg = (m) => (this.materials.push(m), m);

    const surname = def.name.replace(/"[^"]*"\s*/g, '').trim().split(' ').pop();
    const shirtMap = shirtTexture({
      shirt: kit.shirt,
      trim: kit.trim,
      number: def.number,
      name: surname,
      sponsor: def.sponsor || (keeper ? 'KICKSTRIKE' : 'VOLTA'),
      yToV: (f) => f,
    });
    const shirt = reg(fabricMaterial(kit.shirt, shirtMap));
    const sleeveMat = reg(fabricMaterial(kit.shirt));
    const trim = reg(fabricMaterial(kit.trim));
    const shorts = reg(fabricMaterial(kit.shorts));
    const socks = reg(fabricMaterial(kit.socks));
    const skin = reg(skinMaterial(look.skin));
    const glove = reg(fabricMaterial(0xf4f4f4));

    // ---- Hips & shorts
    this.hips = new THREE.Group();
    this.hips.position.y = 0.95 * H;
    this.body.add(this.hips);
    const pelvis = mesh(limbGeometry([[0, 0.2], [0.3, 0.215], [1, 0.226]], 0.26, B, 0.72), shorts, this.hips, 0, 0.08, 0);
    this._hit(pelvis, 'body');

    // ---- Legs
    this.legs = [];
    for (const side of [-1, 1]) {
      const thigh = new THREE.Group();
      thigh.position.set(side * 0.11 * B, -0.1, 0);
      this.hips.add(thigh);
      const tm = mesh(limbGeometry(PROFILES.thigh, 0.47 * H, B), skin, thigh);
      this._hit(tm, 'body');
      mesh(limbGeometry([[0, 0.118], [1, 0.111]], 0.19, B), shorts, thigh, 0, 0.03, 0);
      const shin = new THREE.Group();
      shin.position.y = -0.46 * H;
      thigh.add(shin);
      mesh(jointGeometry(0.06 * B), skin, shin, 0, 0, 0.005);
      mesh(limbGeometry(PROFILES.knee, 0.08 * H, B * 1.02), skin, shin, 0, 0.01, 0);
      const sm = mesh(limbGeometry(PROFILES.calf, 0.38 * H, B * 1.04), socks, shin, 0, -0.07 * H, 0);
      this._hit(sm, 'body');
      const band = mesh(new THREE.TorusGeometry(0.064 * B, 0.008, 6, 20), trim, shin, 0, -0.08 * H, 0);
      band.rotation.x = Math.PI / 2;
      mesh(jointGeometry(0.04 * B), socks, shin, 0, -0.44 * H, 0);
      const boot = buildBoot(kit.boots, keeper ? 0x111111 : 0xffffff);
      boot.materials.forEach(reg);
      const foot = boot.foot;
      foot.position.y = -0.44 * H;
      shin.add(foot);
      this.legs.push({ thigh, shin, foot, side });
    }

    // ---- Torso (one shaped lathe: waist → chest → shoulders → neck base)
    this.torso = new THREE.Group();
    this.torso.position.y = 0.08;
    this.hips.add(this.torso);
    const top = 0.635 * H;
    const L = top + 0.1;
    const T = (y) => (top - y) / L;
    const torsoKeys = [
      [T(top), 0.06], [T(0.625 * H), 0.078], [T(0.6 * H), 0.15], [T(0.55 * H), 0.218], [T(0.48 * H), 0.238],
      [T(0.38 * H), 0.236], [T(0.25 * H), 0.215], [T(0.12 * H), 0.196], [T(0), 0.188], [T(-0.1), 0.19],
    ];
    const chest = mesh(limbGeometry(torsoKeys, L, B, 0.62, 28), shirt, this.torso, 0, top, 0);
    this._hit(chest, 'body');
    const collar = mesh(new THREE.TorusGeometry(0.068, 0.014, 8, 24), trim, this.torso, 0, 0.627 * H, 0.004);
    collar.rotation.x = Math.PI / 2;
    collar.scale.set(1, 0.85, 1);
    if (def.armband) this.armbandMat = reg(fabricMaterial(0xffd400));

    // ---- Neck & head
    this.neck = new THREE.Group();
    this.neck.position.y = 0.64 * H;
    this.torso.add(this.neck);
    mesh(limbGeometry(PROFILES.neck, 0.15, 1), skin, this.neck, 0, 0.13, 0);
    this.head = new THREE.Group();
    this.head.position.y = 0.2;
    this.neck.add(this.head);
    const face = buildHead({
      skin: look.skin,
      skinMat: skin,
      hairColor: look.hair,
      hairStyle: look.hairStyle,
      eyes: look.eyes,
      face: look.face || {},
      keeper,
      headband: keeper ? trim : null,
    });
    face.materials.forEach(reg);
    this.head.add(face.group);
    this._hit(face.headMesh, 'head');

    // ---- Arms
    this.arms = [];
    for (const side of [-1, 1]) {
      const shoulder = new THREE.Group();
      shoulder.position.set(side * 0.27 * B, 0.55 * H, 0);
      this.torso.add(shoulder);
      mesh(jointGeometry(0.07 * B), sleeveMat, shoulder, 0, -0.005, 0);
      const armMat = keeper ? sleeveMat : skin;
      const upper = mesh(limbGeometry(PROFILES.upperArm, 0.31 * H, B), armMat, shoulder);
      this._hit(upper, 'body');
      const sleeve = mesh(limbGeometry([[0, 0.076], [0.7, 0.071], [1, 0.073]], 0.14 * H, B), sleeveMat, shoulder, 0, 0.01, 0);
      this._hit(sleeve, 'body');
      const cuff = mesh(new THREE.TorusGeometry(0.072 * B, 0.007, 6, 18), trim, shoulder, 0, -0.13 * H, 0);
      cuff.rotation.x = Math.PI / 2;
      if (def.armband && side === -1) {
        const ab = mesh(new THREE.TorusGeometry(0.066 * B, 0.014, 6, 18), this.armbandMat, shoulder, 0, -0.19 * H, 0);
        ab.rotation.x = Math.PI / 2;
      }
      const elbow = new THREE.Group();
      elbow.position.y = -0.3 * H;
      shoulder.add(elbow);
      mesh(jointGeometry(0.046 * B), armMat, elbow);
      const fore = mesh(limbGeometry(PROFILES.forearm, 0.27 * H, B), armMat, elbow);
      this._hit(fore, 'body');
      const wrist = new THREE.Group();
      wrist.position.y = -0.27 * H;
      elbow.add(wrist);
      const h = buildHand(keeper ? glove : skin, side, keeper ? { curl: 0.25, scale: 1.4 } : { curl: 0.5 });
      wrist.add(h.hand);
      if (keeper) {
        this._hit(h.palm, 'glove');
        const strap = mesh(new THREE.TorusGeometry(0.036, 0.012, 6, 16), trim, wrist, 0, -0.01, 0);
        strap.rotation.x = Math.PI / 2;
      }
      this.arms.push({ shoulder, elbow, side });
    }

    // Overhead indicators: health bar + tackle warning
    this.barCanvas = document.createElement('canvas');
    this.barCanvas.width = 128;
    this.barCanvas.height = 20;
    this.barTex = new THREE.CanvasTexture(this.barCanvas);
    this.bar = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.barTex, depthTest: false, transparent: true }));
    this.bar.scale.set(0.9, 0.14, 1);
    this.bar.position.y = 2.25 * H;
    this.bar.renderOrder = 10;
    this.bar.visible = false;
    this.root.add(this.bar);
    this.drawBar(1);

    const wc = document.createElement('canvas');
    wc.width = wc.height = 64;
    const wg = wc.getContext('2d');
    wg.fillStyle = '#ff2a2a';
    wg.beginPath();
    wg.moveTo(32, 2);
    wg.lineTo(62, 58);
    wg.lineTo(2, 58);
    wg.closePath();
    wg.fill();
    wg.fillStyle = '#fff';
    wg.font = 'bold 40px Arial';
    wg.textAlign = 'center';
    wg.fillText('!', 32, 52);
    const wt = new THREE.CanvasTexture(wc);
    wt.colorSpace = THREE.SRGBColorSpace;
    this.warn = new THREE.Sprite(new THREE.SpriteMaterial({ map: wt, depthTest: false, transparent: true }));
    this.warn.scale.set(0.45, 0.45, 1);
    this.warn.position.y = 2.6 * H;
    this.warn.renderOrder = 11;
    this.warn.visible = false;
    this.root.add(this.warn);

    this.flashT = 0;
    this.pose = { lean: 0, crouch: 0 };
  }

  _hit(m, part) {
    m.userData.part = part;
    this.hitMeshes.push(m);
  }

  drawBar(frac) {
    const g = this.barCanvas.getContext('2d');
    g.clearRect(0, 0, 128, 20);
    g.fillStyle = 'rgba(0,0,0,0.65)';
    g.fillRect(0, 0, 128, 20);
    g.fillStyle = frac > 0.5 ? '#3ddc84' : frac > 0.25 ? '#ffc23d' : '#ff3d3d';
    g.fillRect(3, 3, Math.max(0, 122 * frac), 14);
    this.barTex.needsUpdate = true;
  }

  flash(color = 0xffffff, strength = 1) {
    this.flashT = 0.12 * strength;
    this.flashColor = color;
  }

  updateFlash(dt) {
    if (this.flashT > 0) {
      this.flashT -= dt;
      const k = Math.max(0, this.flashT / 0.12);
      for (const m of this.materials) {
        m.emissive.setHex(this.flashColor);
        m.emissiveIntensity = k * 1.4;
      }
      if (this.flashT <= 0) for (const m of this.materials) m.emissiveIntensity = 0;
    }
  }

  // ---- Poses -----------------------------------------------------------
  // All pose functions write joint rotations directly; the opponent state
  // machine picks which ones to call each frame.

  resetJoints() {
    this.hips.position.y = 0.95 * this.scaleH;
    this.hips.rotation.set(0, 0, 0);
    this.torso.rotation.set(0, 0, 0);
    this.neck.rotation.set(0, 0, 0);
    for (const L of this.legs) {
      L.thigh.rotation.set(0, 0, 0);
      L.shin.rotation.set(0, 0, 0);
      L.foot.rotation.set(0, 0, 0);
    }
    for (const A of this.arms) {
      A.shoulder.rotation.set(0, 0, A.side * 0.12);
      A.elbow.rotation.set(0, 0, 0);
    }
  }

  run(phase, amount, lean = 0.18) {
    this.legs.forEach((L, i) => {
      const p = phase + (i ? Math.PI : 0);
      L.thigh.rotation.x = -Math.sin(p) * 0.8 * amount;
      L.shin.rotation.x = (Math.max(0, Math.cos(p)) * 1.3 + 0.1) * amount;
    });
    this.arms.forEach((A, i) => {
      const p = phase + (i ? 0 : Math.PI);
      A.shoulder.rotation.x = -Math.sin(p) * 0.8 * amount;
      A.elbow.rotation.x = -0.9 * amount - 0.2;
    });
    this.torso.rotation.x = lean * amount;
    this.hips.position.y = 0.95 * this.scaleH + Math.abs(Math.sin(phase)) * 0.05 * amount;
  }

  readyStance(t, crouch = 0.15) {
    // Bouncing on toes, arms slightly out
    const b = Math.sin(t * 8) * 0.02;
    this.hips.position.y = (0.95 - crouch * 0.3) * this.scaleH + b;
    this.legs.forEach((L) => {
      L.thigh.rotation.x = -crouch * 1.4;
      L.shin.rotation.x = crouch * 2.6;
      L.foot.rotation.x = -crouch * 1.1;
      L.thigh.rotation.z = L.side * 0.12;
    });
    this.torso.rotation.x = crouch * 1.2;
    this.neck.rotation.x = -crouch * 1.0;
    this.arms.forEach((A) => {
      A.shoulder.rotation.z = A.side * 0.35;
      A.shoulder.rotation.x = -0.3;
      A.elbow.rotation.x = -0.6;
    });
  }

  strafe(phase, amount, dir) {
    this.legs.forEach((L, i) => {
      const p = phase + (i ? Math.PI : 0);
      L.thigh.rotation.z = L.side * (0.15 + Math.max(0, Math.sin(p)) * 0.35 * amount);
    });
    this.torso.rotation.z = -dir * 0.08 * amount;
  }

  keeperStance(t) {
    this.readyStance(t, 0.28);
    this.arms.forEach((A) => {
      A.shoulder.rotation.z = A.side * 1.0;
      A.shoulder.rotation.x = -0.6;
      A.elbow.rotation.x = -0.5;
    });
  }

  windup(k) {
    // Crouch and coil, arms back — the telegraph before a tackle.
    this.hips.position.y = (0.95 - 0.12 * k) * this.scaleH;
    this.torso.rotation.x = 0.55 * k;
    this.neck.rotation.x = -0.5 * k;
    this.legs.forEach((L, i) => {
      L.thigh.rotation.x = (i ? 0.5 : -0.9) * k;
      L.shin.rotation.x = 1.1 * k;
    });
    this.arms.forEach((A) => {
      A.shoulder.rotation.x = 0.9 * k;
      A.shoulder.rotation.z = A.side * 0.4 * k;
    });
  }

  slideTackle(k) {
    // Low lunge with one leg extended.
    this.hips.position.y = (0.95 - 0.35 * k) * this.scaleH;
    this.torso.rotation.x = -0.35 * k;
    this.legs[1].thigh.rotation.x = -1.4 * k;
    this.legs[1].shin.rotation.x = 0.1;
    this.legs[0].thigh.rotation.x = 0.3 * k;
    this.legs[0].shin.rotation.x = 1.6 * k;
    this.arms.forEach((A) => {
      A.shoulder.rotation.z = A.side * 1.1 * k;
    });
  }

  flinch(k, dirX = 0) {
    this.torso.rotation.x += -0.45 * k;
    this.torso.rotation.z += dirX * 0.25 * k;
    this.neck.rotation.x += -0.5 * k;
    this.arms.forEach((A) => (A.shoulder.rotation.x += 0.6 * k));
  }

  fall(k) {
    // k: 0..1 falling backwards; arms flail then splay out.
    const e = k < 1 ? 1 - Math.pow(1 - k, 3) : 1;
    const bounce = k > 0.85 ? Math.sin((k - 0.85) * 20) * 0.03 * (1 - k) * 6 : 0;
    this.body.rotation.x = -Math.PI / 2 * e + bounce;
    this.body.position.y = 0.12 * e;
    this.legs.forEach((L) => {
      L.thigh.rotation.x = -0.4 * e;
      L.shin.rotation.x = 0.5 * e;
      L.thigh.rotation.z = L.side * 0.25 * e;
    });
    this.arms.forEach((A) => {
      A.shoulder.rotation.z = A.side * (0.3 + 1.2 * e);
      A.shoulder.rotation.x = -0.6 * (1 - e) + 0.3 * e;
      A.elbow.rotation.x = -0.4 * e;
    });
    this.neck.rotation.x = 0.4 * e;
  }

  dive(k, dir) {
    // Keeper dive: roll sideways and stretch out.
    const s = Math.sin(Math.min(1, k) * Math.PI);
    this.body.rotation.z = -dir * 1.25 * Math.min(1, k * 1.8) * (k < 0.8 ? 1 : 1 - (k - 0.8) * 2.5);
    this.body.position.y = s * 0.55;
    this.arms.forEach((A) => {
      A.shoulder.rotation.z = A.side * 2.6 * Math.min(1, k * 2);
      A.elbow.rotation.x = -0.1;
    });
    this.legs.forEach((L) => (L.thigh.rotation.z = L.side * 0.3));
  }

  throwArm(k) {
    // Overarm throw with the right arm.
    const A = this.arms[1];
    if (k < 0.6) {
      A.shoulder.rotation.x = THREE.MathUtils.lerp(-0.3, 2.8, k / 0.6);
      A.elbow.rotation.x = THREE.MathUtils.lerp(-0.4, -1.4, k / 0.6);
      this.torso.rotation.y = -0.4 * (k / 0.6);
    } else {
      const u = Math.min(1, (k - 0.6) / 0.4);
      A.shoulder.rotation.x = THREE.MathUtils.lerp(2.8, -1.2, u);
      A.elbow.rotation.x = THREE.MathUtils.lerp(-1.4, -0.1, u);
      this.torso.rotation.y = THREE.MathUtils.lerp(-0.4, 0.3, u);
      this.torso.rotation.x = 0.3 * u;
    }
  }
}
